import { reduceMotion } from './env.ts';
import { nextHue } from './hues.ts';

/**
 * The controls above the grid: three densities, and a switch between equal
 * heights and relative sizes.
 */
const MORPH_MS = 500;

export function initControls(): void {
  const grid = document.querySelector<HTMLElement>('[data-grid]');
  const root = document.querySelector<HTMLElement>('[data-controls]');
  if (!grid || !root) return;

  const press = (buttons: Iterable<HTMLButtonElement>, active: HTMLButtonElement) => {
    const n = nextHue();
    for (const b of buttons) {
      const on = b === active;
      b.classList.toggle('is-active', on);
      b.setAttribute('aria-pressed', String(on));
      b.style.color = on && n >= 0 ? `var(--neg-${n})` : '';
    }
  };
  const changed = () => grid.dispatchEvent(new Event('gridchange'));

  const densities = root.querySelectorAll<HTMLButtonElement>('[data-density]');
  for (const button of densities) {
    button.addEventListener('click', () => {
      morph(grid, () => grid.style.setProperty('--unit', button.dataset.density ?? ''));
      press(densities, button);
      changed();
    });
  }

  /* The sizing switch is only offered where the tiles were given their real sizes to draw at. */
  const scales = root.querySelectorAll<HTMLButtonElement>('[data-scale]');
  if (grid.hasAttribute('data-scalable')) {
    for (const button of scales) {
      button.addEventListener('click', () => {
        morph(grid, () => grid.classList.toggle('grid-scaled', button.dataset.scale === 'real'));
        press(scales, button);
        changed();
      });
    }
  } else {
    for (const button of scales) button.closest('.control-group')?.remove();
  }

  // The ones pressed on arrival take their colour too.
  for (const group of [densities, scales]) {
    const active = [...group].find((b) => b.classList.contains('is-active'));
    if (active) press(group, active);
  }
}

/** Change the grid and let every painting travel to its new place. */
function morph(grid: HTMLElement, change: () => void): void {
  if (reduceMotion.matches || grid.classList.contains('is-stacked')) { change(); return; }

  const tiles = [...grid.querySelectorAll<HTMLElement>('.tile')].filter((t) => !t.hidden);
  const before = tiles.map((t) => t.getBoundingClientRect());
  change();
  tiles.forEach((tile, i) => {
    const was = before[i]!;
    const now = tile.getBoundingClientRect();
    if (!was.width || !now.width) return;
    // The tiles turn about their centre (the pile needs that), so the move is the move of the
    // centre, and the size the ratio of the two boxes.
    const dx = (was.left + was.width / 2) - (now.left + now.width / 2);
    const dy = (was.top + was.height / 2) - (now.top + now.height / 2);
    const sx = was.width / now.width;
    const sy = was.height / now.height;
    if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5 && Math.abs(sx - 1) < 0.002 && Math.abs(sy - 1) < 0.002) return;
    tile.animate(
      [{ transform: `translate(${dx}px, ${dy}px) scale(${sx}, ${sy})` }, { transform: 'none' }],
      { duration: MORPH_MS, easing: 'cubic-bezier(0.22, 1, 0.36, 1)' },
    );
  });
}
